# region: intake
def intake(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: digest
def digest(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
        return out
    return out

# region: render
def render(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: sift
def sift(summary, name='alpha'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return sift(render(digest(intake(raw))))

